FuncDef.Code:
vec3 backdropAnimatedColors(in vec3 dir, in vec3 color0, in vec3 color1, in vec3 color2, in vec3 color3, in float animSpeed)
{
    // animated bg
    float t = animSpeed * iTime;
    vec3 dir1 = vec3(sin(0.55 * t)  , sin(0.88 * t) , 1.0           );
    vec3 dir2 = vec3(sin(0.77 * t)  , 1.0           , sin(0.55 * t) );
    vec3 dir3 = vec3(1.0            , sin(0.66 * t) , sin(0.44 * t) );

    dir = normalize(dir);

    float dot1 = dot(dir, normalize(dir1));
    float dot2 = dot(dir, normalize(dir2));
    float dot3 = dot(dir, normalize(dir3));

    dot1 = 0.5 * dot1 + 0.5;
    dot2 = 0.5 * dot2 + 0.5;
    dot3 = 0.5 * dot3 + 0.5;

    vec3 colOut = color0 + dot1 * color1 + dot2 * color2 + dot3 * color3;

    return colOut;
}
